statement:
Decide whether the string `word` is valid, returning `true` or `false`. It is valid exactly when all four rules hold:

- its length is 3 or more;
- every character is a digit (`0`-`9`) or an English letter of either case;
- at least one character is a vowel;
- at least one character is a consonant.

The vowels are `a`, `e`, `i`, `o`, `u` in lowercase or uppercase. A consonant is any English letter that is not a vowel (so `y` is a consonant). Digits are neither.

validator:
function validate([word]) {
  if (typeof word !== 'string' || word.length < 1 || word.length > 20) return 'word needs 1 to 20 characters.';
  if (!/^[A-Za-z0-9@#$]+$/.test(word)) return 'word may contain only letters, digits, "@", "#" and "$".';
  return null;
}

reference:
function isValid(word) {
  if (word.length < 3) {
    return false;
  }
  let hasVowel = false;
  let hasConsonant = false;
  for (const ch of word) {
    if (ch >= '0' && ch <= '9') {
      continue;
    }
    const lower = ch.toLowerCase();
    if (lower < 'a' || lower > 'z') {
      return false;
    }
    if ('aeiou'.includes(lower)) {
      hasVowel = true;
    } else {
      hasConsonant = true;
    }
  }
  return hasVowel && hasConsonant;
}

brute:
function isValid(word) {
  // Test each rule with its own regular expression.
  const allowed = /^[A-Za-z0-9]{3,}$/.test(word);
  const vowel = /[aeiouAEIOU]/.test(word);
  const consonant = /[b-df-hj-np-tv-zB-DF-HJ-NP-TV-Z]/.test(word);
  return allowed && vowel && consonant;
}

