function generate(rand, size) {
  const groups = ['aeiouAEIOU', 'bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ', '0123456789', '@#$'];
  const n = size === 'large' ? 15 + Math.floor(rand() * 6) : 1 + Math.floor(rand() * 6);
  // Choose which kinds of character may appear, so every rule is broken in some inputs and kept in others.
  const pools = groups.filter((_, k) => rand() < (k === 3 ? 0.25 : 0.7));
  if (!pools.length) pools.push(groups[2]);
  let word = '';
  for (let i = 0; i < n; i++) {
    const pool = pools[Math.floor(rand() * pools.length)];
    word += pool[Math.floor(rand() * pool.length)];
  }
  return [word];
}
